// Línea temporal de la política española desde la muerte de Franco (1975). Criterio: hechos que cambiaron quién
// gobierna, qué leyes rigen o el contexto en que se vota; contados sin adjetivos y con fuente.
// Tribunales: entran las causas que afectan a un partido con escaño, a un Gobierno o a su entorno
// cuando hay imputación conocida, juicio o sentencia, sea del partido que sea, y siempre con el
// estado procesal exacto (si la sentencia no es firme, se dice).
// Fuentes: BOE para leyes, Ministerio del Interior para elecciones, medios para lo reciente y
// Wikipedia como lectura ampliada de los hechos más antiguos.
export type Categoria = 'elecciones' | 'gobierno' | 'leyes' | 'economia' | 'territorio' | 'tribunales' | 'sociedad' | 'internacional';

export const categorias: Record<Categoria, { label: string; color: string }> = {
  elecciones: { label: 'Elecciones', color: 'var(--gold)' },
  gobierno: { label: 'Gobierno', color: 'var(--purple)' },
  leyes: { label: 'Leyes', color: 'var(--green)' },
  economia: { label: 'Economía', color: '#3a7bd5' },
  territorio: { label: 'Cataluña y territorio', color: 'var(--terracotta)' },
  tribunales: { label: 'Tribunales', color: 'var(--red)' },
  sociedad: { label: 'Sociedad y crisis', color: '#7a6a58' },
  internacional: { label: 'Europa y mundo', color: '#2a9d8f' },
};

export interface Evento {
  /** aaaa-mm-dd (o aaaa-mm si no hay día concreto). */
  fecha: string;
  titulo: string;
  categoria: Categoria;
  texto: string;
  /** Hechos que marcan la legislatura: se ven más grandes. */
  clave?: boolean;
  fuente?: { titulo: string; url: string };
  enlaces?: { texto: string; href: string }[];
}

const L = (slug: string, texto: string) => ({ texto, href: `/aprende/politica/${slug}/` });
const P = (id: string, texto: string) => ({ texto, href: `/aprende/politica/partidos/${id}/` });
const BOE = (id: string, titulo: string) => ({ titulo, url: `https://www.boe.es/buscar/doc.php?id=${id}` });
const WIKI = (articulo: string, titulo = 'Más información (Wikipedia)') => ({ titulo, url: `https://es.wikipedia.org/wiki/${articulo}` });
const INTERIOR = { titulo: 'Resultados oficiales (Ministerio del Interior)', url: 'https://infoelectoral.interior.gob.es/' };

